-- ---------------------------------------------------------------------
-- 2. TABELA PRINCIPAL DE CONVÊNIOS E TRANSFERÊNCIAS (SISTEMA ENESITO)
-- ---------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS `convenios` (
  `id` INT(11) NOT NULL AUTO_INCREMENT,
  `numero_convenio` VARCHAR(50) NOT NULL,
  `numero_proposta` VARCHAR(50) DEFAULT NULL,
  `id_proposta` VARCHAR(50) DEFAULT NULL,
  `data_assinatura` DATE DEFAULT NULL,
  `inicio_vigencia` DATE DEFAULT NULL,
  `fim_vigencia` DATE DEFAULT NULL,
  `dias_ate_fim_vigencia` INT(11) DEFAULT NULL,
  `status_prazo` VARCHAR(100) DEFAULT NULL,
  `status_transferegov` VARCHAR(150) DEFAULT NULL,
  `categoria_executiva` VARCHAR(100) DEFAULT NULL,
  `semaforo` VARCHAR(50) DEFAULT NULL,
  `classificacao_risco` VARCHAR(50) DEFAULT NULL,
  `pendencia_parado` VARCHAR(10) DEFAULT 'Não',
  `ministerio_concedente` VARCHAR(255) DEFAULT NULL,
  `orgao_concedente` VARCHAR(255) DEFAULT NULL,
  `programa_id` VARCHAR(50) DEFAULT NULL,
  `objeto` TEXT DEFAULT NULL,
  `proponente` VARCHAR(255) DEFAULT NULL,
  `cnpj_proponente` VARCHAR(20) DEFAULT NULL,
  `municipio_proponente` VARCHAR(100) DEFAULT 'RIO DE JANEIRO',
  `valor_global` DECIMAL(15,2) NOT NULL DEFAULT 0.00,
  `valor_repasse` DECIMAL(15,2) NOT NULL DEFAULT 0.00,
  `valor_desembolsado` DECIMAL(15,2) NOT NULL DEFAULT 0.00,
  `saldo_a_desembolsar` DECIMAL(15,2) NOT NULL DEFAULT 0.00,
  `valor_empenhado` DECIMAL(15,2) NOT NULL DEFAULT 0.00,
  `saldo_em_conta` DECIMAL(15,2) NOT NULL DEFAULT 0.00,
  `ultima_movimentacao_financeira` VARCHAR(255) DEFAULT NULL,
  `e_pac` VARCHAR(10) NOT NULL DEFAULT 'Não',
  `nr_reservado_pac` VARCHAR(100) DEFAULT NULL,
  `criado_em` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `atualizado_em` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_convenio` (`numero_convenio`),
  KEY `idx_ministerio` (`ministerio_concedente`),
  KEY `idx_proponente` (`proponente`),
  KEY `idx_categoria` (`categoria_executiva`),
  KEY `idx_semaforo` (`semaforo`),
  KEY `idx_status_prazo` (`status_prazo`),
  KEY `idx_pac` (`e_pac`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

